"""Public programme updates and an optional, progressively enhanced miniature."""
from pathlib import Path
from html import escape as e
import json

DATA=json.loads((Path(__file__).resolve().parents[1]/'programme-content.json').read_text())
IDS=['cafe','coffee','workshops','local']

def payload(key,api_origin,programme_url):
    d={'copy':DATA['copy'][key],'initial':DATA['initial'],'language':key,'apiOrigin':api_origin,'programmeUrl':programme_url}
    return '<script type="application/json" id="programme-data">'+json.dumps(d,ensure_ascii=False).replace('<','\\u003c')+'</script>'

def weather(c,compact=False):
    w=c['weather']
    return f'''<div class="programme-weather {'is-compact' if compact else ''}" aria-label="{e(w['title'])}"><div class="programme-clock"><span class="weather-live-dot" aria-hidden="true"></span><span><span class="eyebrow">{e(w['title'])}</span><time data-programme-time>{e(w['time'])}</time></span><span class="programme-day" data-programme-day></span></div><p data-weather-status class="weather-condition">{e(w['unavailable'])}</p><dl class="weather-numbers"><div><dt>{e(w['temperature'])}</dt><dd data-weather-temperature>—</dd></div><div><dt>{e(w['wind'])}</dt><dd data-weather-wind>—</dd></div><div><dt>{e(w['rain'])}</dt><dd data-weather-rain>—</dd></div></dl><p class="weather-asof" data-weather-asof></p></div>'''

def world(c,compact=False):
    options=''.join(f'<button type="button" data-programme-department="{id}" aria-pressed="false">{e(c["departments"][id]["title"])}</button>' for id in IDS)
    quick='' if compact else f'''<div class="programme-growth-quick" data-growth-previewbar hidden><p><span data-preview-label>{e(c['growth']['actualLabel'])}</span><strong data-preview-stage></strong></p><div><button type="button" data-growth-previous aria-label="{e(c['growth']['previousStage'])}">←</button><button type="button" data-growth-next aria-label="{e(c['growth']['nextStage'])}">→</button><button type="button" data-growth-stage="actual">{e(c['growth']['resetActual'])}</button></div></div>'''
    return f'''<div class="programme-world-root {'programme-home-world' if compact else ''}" data-programme-world><div class="programme-world-toolbar"><span class="eyebrow">{e(c['homeEntryKicker'] if compact else c['kicker'])}</span><div class="programme-world-actions"><button type="button" class="programme-reset" data-programme-reset aria-label="{e(c['reset'])}" title="{e(c['reset'])}">↺</button><button type="button" data-programme-pause aria-pressed="true">{e(c['resume'])}</button></div></div><div class="programme-canvas-wrap"><canvas id="programme-world-canvas" tabindex="0" aria-label="{e(c['title'])}" aria-describedby="programme-world-caption"></canvas><img class="programme-poster" src="/assets/progress/programme-poster.webp" alt="{e(c['worldCaption'])}" width="1200" height="800" decoding="async" {'loading="eager"' if compact else ''}><p class="programme-loading" data-programme-loading hidden>{e(c['loading'])}</p><p class="programme-fallback" data-programme-fallback hidden>{e(c['fallback'])}</p><div class="programme-thought" data-programme-thought aria-hidden="true" hidden><span></span><i></i></div><span class="programme-world-drag">{e(c['drag'])}</span></div><div class="programme-department-tabs" role="group" aria-label="{e(c['viewDepartment'])}"><button type="button" data-programme-department="all" aria-pressed="true">{e(c['overview'])}</button>{options}</div>{quick}<p class="programme-world-caption" id="programme-world-caption">{e(c['worldCaption'])} <span>{e(c['staffCaption'])}</span></p></div>'''

def cards(key):
    c=DATA['copy'][key]
    result=''
    for i,id in enumerate(IDS):
        d=DATA['initial']['departments'][id];t=d['translations'][key]
        done=''.join('<li>'+e(s)+'</li>' for s in t['done'])
        result+=f'''<article class="programme-card" id="programme-{id}" data-department-card="{id}"><div class="programme-card-top"><span class="programme-index">0{i+1}</span><span class="programme-status" data-status>{e(c['statusLabels'][d['status']])}</span></div><h3>{e(c['departments'][id]['title'])}</h3><dl><div><dt>{e(c['now'])}</dt><dd data-now>{e(t['now'])}</dd></div><div class="programme-next"><dt>{e(c['next'])}</dt><dd data-next>{e(t['next'])}</dd></div></dl><div class="programme-done"><span>{e(c['done'])}</span><ul data-done {'hidden' if not done else ''}>{done}</ul><p data-no-done {'' if not done else 'hidden'}>{e(c['noDone'])}</p></div></article>'''
    return result

def home(key,api_origin,programme_url):
    c=DATA['copy'][key]
    return world(c,True)+weather(c,True)+f'<p class="programme-home-credit">{e(c["weather"]["source"])}: <a href="https://api.met.no/">MET Norway</a> · <a href="https://creativecommons.org/licenses/by/4.0/" rel="license">CC BY 4.0</a>. {e(c["weather"]["estimated"])}</p>'+f'<a class="programme-hero-link text-link" href="{programme_url}">{e(c["homeEntryButton"])} <span aria-hidden="true">↗</span></a>'+payload(key,api_origin,programme_url)

def entry(key,programme_url):
    c=DATA['copy'][key]
    return f'''<section class="programme-entry section"><div><p class="eyebrow">{e(c['homeEntryKicker'])}</p><h2>{e(c['progressLink'])}</h2></div><div><p>{e(c['progressLinkBody'])}</p><a class="text-link" href="{programme_url}">{e(c['homeEntryButton'])}<span aria-hidden="true">↗</span></a></div></section>'''

def page(key,api_origin,home_url,progress_url,programme_url,register_url):
    c=DATA['copy'][key];g=c['growth'];w=c['weather'];p=DATA['initial']['coffee']
    static_stages=''.join(f'<article><h3>{e(v["title"])}</h3><p>{e(v["body"])}</p></article>' for v in g['stages'].values())
    stages=''.join(f'<button type="button" data-growth-stage="{id}" aria-pressed="false">{e(value["title"])}</button>' for id,value in g['stages'].items())
    return f'''<nav class="programme-breadcrumb section" aria-label="{e(c['breadcrumbCurrent'])}"><a href="{home_url}">{e(c['breadcrumbHome'])}</a><span aria-hidden="true">/</span><a href="{progress_url}">{e(c['breadcrumbProgress'])}</a><span aria-hidden="true">/</span><span aria-current="page">{e(c['breadcrumbCurrent'])}</span></nav><section class="programme-intro section"><div><p class="eyebrow">{e(c['kicker'])}</p><h1>{e(c['title'])}</h1><p class="lead">{e(c['intro'])}</p></div>{weather(c)}</section><section class="programme-scene section">{world(c)}</section><section class="programme-updates section" id="department-updates"><div class="section-heading"><div><p class="eyebrow">{e(c['updatesTitle'])}</p><h2>{e(c['departmentsTitle'])}</h2></div><div><p>{e(c['departmentsIntro'])}</p><p class="programme-update-date">{e(c['updatedOn'])} <time data-programme-updated datetime="{DATA['initial']['updatedAt']}">{DATA['initial']['updatedAt']}</time></p></div></div><p data-programme-data-status class="small" role="status">{e(c['latestUpdate'])} · {DATA['initial']['updatedAt']}</p><div class="programme-cards">{cards(key)}</div></section><section class="programme-growth section" id="coffee-growth"><div class="programme-growth-heading"><p class="eyebrow">{e(g['kicker'])}</p><h2>{e(g['title'])}</h2><p>{e(g['intro'])}</p></div><div class="programme-plant-records"><article><span class="eyebrow">{e(g['seedTrack'])}</span><h3>IPR107 · NR25 · Marsellesa</h3><p data-seed-actual>{e(g['seedActual'])}</p></article><article><span class="eyebrow">{e(g['trialTrack'])}</span><h3>Paraíso <span data-plant-height>~20 cm</span></h3><p data-trial-actual>{e(g['trialActual'])}</p></article></div><p class="small programme-observed">{e(g['observedOn'])} <time data-plant-observed datetime="{p['observedOn']}">{p['observedOn']}</time> · {e(c['reportedByOwner'])}</p><details class="growth-explorer"><summary>{e(g['selectStage'])}<span aria-hidden="true">+</span></summary><div class="growth-explorer-content"><div class="growth-static-notes">{static_stages}</div><p class="eyebrow" data-growth-label>{e(g['actualLabel'])}</p><div class="growth-stage-buttons" role="group" aria-label="{e(g['selectStage'])}"><button type="button" data-growth-stage="actual" aria-pressed="true">{e(g['resetActual'])}</button>{stages}</div><article class="growth-description"><h3 data-growth-title>{e(g['actualLabel'])}</h3><p data-growth-body>{e(g['futureNote'])}</p><a class="text-link" href="#programme-world-canvas">{e(c['viewDepartment'])}<span aria-hidden="true">↑</span></a></article><p class="small">{e(g['graftNote'])}</p></div></details><p class="small programme-variety-note">{e(g['varietyNote'])}</p></section><aside class="programme-weather-credit section"><p>{e(w['source'])}: <a href="https://api.met.no/" rel="external">MET Norway</a> · <a href="https://creativecommons.org/licenses/by/4.0/" rel="license">CC BY 4.0</a>. {e(w['estimated'])}</p></aside><section class="signup-band"><div><p class="eyebrow">{e(c['subscribeKicker'])}</p><h2>{e(c['subscribeTitle'])}</h2><p>{e(c['subscribeBody'])}</p></div><a class="button button-light" href="{register_url}">{e(c['subscribeButton'])}<span aria-hidden="true">↗</span></a></section>'''+payload(key,api_origin,programme_url)
